import {beginDraftScope,endDraftScope,list,keys,lastDraftScopeRow} from './state.mjs';
import {validateBackup} from './backup-model.mjs';
import {esc,icon} from './ui.mjs';
import {withStableView} from './view-stability.mjs';
let active=null;
export const accountDraftHasWork=()=>!!active?.hasWork();
export const accountDraftEditing=()=>!!active;
export const saveAccountDraft=()=>active?.save()??Promise.resolve(false);
export function disposeAccountDraft(){active?.dispose();active=null;endDraftScope();}
export function accountDraftSessionChanged(user){if(active?.observeSession?.(user))return;if(active&&active.userId!==user?.id){active.dispose();active=null;endDraftScope();const root=document.querySelector('.dashboard');if(root)root.innerHTML='<section class="card hub-card"><h1>账户会话已变化</h1><p>请重新打开当前账户的成果。</p><a href="#assets?scope=account">查看账户成果</a></section>';}}
export const accountDraftConfirmLeave=()=>active?.confirmLeave()??Promise.resolve(true);
export const accountDraftRouteGuard=target=>active?.guard(target)??true;
const cleanPayload=raw=>{const payload=structuredClone(raw);for(const field of ['exportUnlocked','paid','isPaid','isAdmin','role','entitlements','payment','paymentStatus','accessToken','token'])delete payload[field];return payload;};
export function safeAccountDraft(item){const raw=cleanPayload({...item.payload,id:item.id,title:item.title,tool:item.tool,projectId:item.project_id||''});return validateBackup({format:'paperknow-workspace-backup',version:1,drafts:[raw]}).drafts[0];}
export async function mountAccountDraft(id,ctx){
 disposeAccountDraft();let alive=true,dirty=false,busy=true,allow=false,userId=null,item=null,observer=null,button=null,revision=0,observedUserId=undefined;const controller=new AbortController();
 const root=document.querySelector('.dashboard');root.dataset.accountEditing='true';root.innerHTML='<section class="card hub-card"><h1>正在读取账户草稿…</h1></section>';
 function notice(message){if(alive)ctx.notify(message);}
 async function api(path,data){const request=new AbortController();const abort=()=>request.abort();controller.signal.addEventListener('abort',abort,{once:true});const timer=setTimeout(()=>request.abort(),20000);try{const response=await fetch('/api'+path,{method:data===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:{...(data===undefined?{}:{'Content-Type':'application/json'}),...(userId?{'X-PaperKnow-User':userId}:{})},body:data===undefined?undefined:JSON.stringify(data),signal:request.signal});const value=await response.json().catch(()=>({error:'服务暂时不可用，请稍后重试'}));if(!alive)throw new DOMException('页面已切换','AbortError');if(!response.ok){if((response.status===409&&value.code==='ACCOUNT_CHANGED')||(response.status===401&&userId)){invalidateAccount();throw new DOMException('账户会话已变化','AbortError');}const e=new Error(value.error||'账户草稿暂时无法保存');e.status=response.status;throw e;}return value;}catch(error){if(request.signal.aborted&&!controller.signal.aborted)throw new Error('连接超时，当前编辑仍保留，请重试保存。');throw error;}finally{clearTimeout(timer);controller.signal.removeEventListener('abort',abort);}}
 function invalidateAccount(){if(active!==instance)return;instance.dispose();active=null;endDraftScope();root.innerHTML='<section class="card hub-card"><h1>账户会话已变化</h1><p>已隐藏原账户编辑内容，请登录原账户后重新打开草稿。</p><a href="#assets?scope=account">查看账户成果</a></section>';}
 const askLeave=()=>new Promise(resolve=>{ctx.modal('账户草稿尚未保存',`<p>当前修改尚未保存回账户。可以保存后离开，或保留原账户版本并放弃这次编辑。</p><div class="actions"><button class="btn secondary" id="cloud-stay">继续编辑</button><button class="btn secondary" id="cloud-discard">放弃本次修改</button><button class="btn primary" id="cloud-save-leave">保存到账户并离开</button></div>`);const dialog=document.querySelector('#workspace-dialog');const finish=value=>{dialog.removeEventListener('close',cancel);dialog.close();resolve(value);};const cancel=()=>finish(false);dialog.addEventListener('close',cancel,{once:true});document.querySelector('#cloud-stay').onclick=()=>finish(false);document.querySelector('#cloud-discard').onclick=()=>finish(true);document.querySelector('#cloud-save-leave').onclick=async()=>{if(await save())finish(true);};});
 function attachBar(){if(!alive||!item)return;return withStableView(root,()=>{let bar=root.querySelector('#account-draft-bar');if(!bar){bar=document.createElement('section');bar.id='account-draft-bar';bar.className='workspace-content-scope account-draft-bar';bar.innerHTML=`<div><b>${icon('user',16)}账户草稿 · <span id="account-draft-version"></span></b><p>在本页编辑后，点击“保存到账户”。当前内容仅在内存中编辑，不写入共享的本地成果。</p><span id="account-draft-status" role="status"></span></div><div class="actions"><a href="#assets?scope=account" class="btn secondary">账户成果</a><button type="button" class="btn primary" id="account-draft-save">保存到账户</button></div>`;root.prepend(bar);button=bar.querySelector('#account-draft-save');button.onclick=()=>void save();}root.querySelectorAll('#writing-status,#support-status,#integrated-status,#research-status,#ppt-status').forEach(node=>{if(/已保存到当前浏览器|文稿已保存|草稿已保存到当前浏览器/.test(node.textContent))node.textContent='已暂存当前编辑页，请点击“保存到账户”同步。';if(!busy&&!dirty&&/^(?:已暂存当前编辑页，请点击“保存到账户”同步。|编辑已暂存，请保存到账户同步。|编辑内容已暂存，尚未保存到账户。|已保留当前编辑，请使用上方“保存到账户”保存到云端。)$/.test(node.textContent))node.textContent='当前编辑已保存到账户。';});root.querySelectorAll('a[href^="#draft/"]').forEach(a=>a.href='#account-draft/'+encodeURIComponent(item.id));root.querySelector('#account-draft-version').textContent='版本 '+item.version;button.disabled=busy;});}
 async function save(){if(!alive||busy||!item)return false;busy=true;attachBar();try{const identity=await api('/auth/me');if(identity.user?.id!==userId)throw new Error('登录账户已变化，请重新打开当前账户的草稿。');const nativeSaved=await ctx.saveNative(item.tool,item.payload);if(!nativeSaved)throw new Error('请先完善必填内容，再保存到账户。');const row=typeof nativeSaved==='object'?nativeSaved:lastDraftScopeRow();if(!row)throw new Error('当前草稿未完成保存，请检查必填内容。');const sentRevision=revision;const response=await api('/workspace/drafts/'+encodeURIComponent(item.id),{version:item.version,title:row.title,projectId:row.projectId||'',payload:cleanPayload(row)});item=response.item;dirty=revision!==sentRevision;notice(dirty?'此前内容已保存，保存期间新增的修改尚未提交，请再次保存。':'已保存到账户，版本 '+item.version+'；其他设备可继续编辑。');return !dirty;}catch(error){if(alive&&error.name!=='AbortError'){notice(error.status===409?'账户中已有更新版本。当前编辑仍保留，请先导出本页内容，再重新打开账户版本；不会覆盖其他设备的修改。':error.status===401?'登录已过期，当前编辑仍保留。请先导出当前内容，再重新登录。':error.message);const status=root.querySelector('#account-draft-status');if(status)status.textContent=error.status===409?'版本冲突：请先导出当前内容，再重新打开账户版本。':error.message;}return false;}finally{busy=false;attachBar();}}
 const instance={save,get userId(){return userId;},observeSession(next){if(userId!==null)return false;observedUserId=next?.id??null;return true;},hasWork:()=>dirty||busy,dispose(){alive=false;controller.abort();delete root.dataset.accountEditing;ctx.disposeNative?.();observer?.disconnect();root.removeEventListener('input',changed,true);root.removeEventListener('change',changed,true);root.removeEventListener('click',clicked,true);},async confirmLeave(){return !dirty&&!busy||(!busy&&await askLeave());},guard(target){if(allow){allow=false;return true;}if(busy){notice('正在读取或保存账户草稿，请稍候。');return false;}if(!dirty)return true;void askLeave().then(ok=>{if(ok&&alive){allow=true;location.hash=target;}});return false;}};active=instance;
 function changed(e){if(!e.target.closest('#account-draft-bar')){dirty=true;revision++;}}
 function clicked(e){if(e.target.closest('#account-draft-bar'))return;const b=e.target.closest('button');if(b&&!/(export|download|copy|csv|svg|png|backup)/i.test((b.id||'')+' '+(b.dataset.action||''))){dirty=true;revision++;}}
 try{const auth=await api('/auth/me');if(!alive)return;if(typeof auth.user?.id!=='string'||!auth.user.id)throw new Error('请先登录账户后重新打开草稿。');if(observedUserId!==undefined&&observedUserId!==auth.user.id)throw new Error('登录账户已变化，请重新打开当前账户的成果。');userId=auth.user.id;const [data,projectData]=await Promise.all([api('/workspace/drafts/'+encodeURIComponent(id)),api('/projects')]);if(!alive)return;item=data.item;const draft=safeAccountDraft(item);beginDraftScope({ownerId:userId,drafts:[draft],projectRows:projectData.items.map(p=>({...p,name:p.title}))});await ctx.mount(draft);if(!alive)return;busy=false;dirty=false;root.addEventListener('input',changed,true);root.addEventListener('change',changed,true);root.addEventListener('click',clicked,true);observer=new MutationObserver(attachBar);observer.observe(root,{childList:true});attachBar();}catch(error){busy=false;if(alive&&error.name!=='AbortError'){root.innerHTML=`<section class="card hub-card"><h1>账户草稿暂不可用</h1><p>${esc(error.message)}</p><a class="btn secondary" href="#assets?scope=account">返回账户成果</a></section>`;notice(error.message);}}
 return instance;
}
if(typeof window!=='undefined'){window.addEventListener('beforeunload',e=>{if(accountDraftHasWork()){e.preventDefault();e.returnValue='';}});document.addEventListener('click',e=>{if(!active||!accountDraftHasWork())return;const a=e.target.closest('a[href]');if(!a||a.target==='_blank'||a.hasAttribute('download')||a.getAttribute('href').startsWith('#'))return;e.preventDefault();e.stopImmediatePropagation();void active.confirmLeave().then(ok=>{if(ok)location.href=a.href;});},true);}
